#!/usr/bin/env node
// Generate docs/catalog.md, the browsable scenario catalog, from scenarios/*.yaml. Every cell
// comes from a scenario file; nothing is typed by hand. The output is pure ASCII.
//
// Usage (from the repository root; no build needed):
//   node scripts/catalog.mjs            write docs/catalog.md
//   node scripts/catalog.mjs --check    exit 1 if the committed docs/catalog.md differs
//   node scripts/catalog.mjs --stdout   print the generated file (tests)
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SCENARIOS = path.join(ROOT, 'scenarios');
const OUT = path.join(ROOT, 'docs', 'catalog.md');

/** Markdown table cell: pipes escaped, ASCII only (a non-ASCII value is an error, not a guess). */
function cell(v) {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim().replace(/\|/g, '\\|');
  if (/[^\x20-\x7e]/.test(s)) throw new Error(`non-ASCII text in catalog cell: ${JSON.stringify(s)}`);
  return s;
}

function disclosure(src) {
  let label;
  const ghsa = /GHSA-[0-9a-z]{4}-[0-9a-z]{4}-[0-9a-z]{4}/.exec(src.primary_url);
  if (src.cve) label = src.cve;
  else if (ghsa) label = ghsa[0];
  else {
    const u = new URL(src.primary_url);
    label = u.hostname.replace(/^www\./, '');
    if (label === 'web.archive.org') label = 'web.archive.org (archived)';
  }
  return `[${cell(label)}](${src.primary_url})${src.date ? ` ${cell(src.date)}` : ''}`;
}

export function generate() {
  const files = readdirSync(SCENARIOS).filter((f) => /\.ya?ml$/i.test(f)).sort();
  const rows = files.map((f) => parse(readFileSync(path.join(SCENARIOS, f), 'utf8')))
    .sort((a, b) => a.id.localeCompare(b.id));
  const runnable = rows.filter((s) => s.runnable === true);
  const byAgent = new Map();
  for (const s of runnable) for (const a of s.applies_to ?? []) byAgent.set(a, (byAgent.get(a) ?? 0) + 1);
  const agents = [...byAgent.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([a, n]) => `${a} ${n}`).join(', ');
  const out = [];
  out.push('# Scenario catalog');
  out.push('');
  out.push('<!-- GENERATED by scripts/catalog.mjs from scenarios/*.yaml. Do not edit by hand: run `npm run catalog`. -->');
  out.push('');
  out.push(`${rows.length} scenarios, ${runnable.length} runnable. Runnable scenarios per agent (\`applies_to\`): ${agents}.`);
  out.push('Scenarios with `runnable: no` are catalogued but not executed (browser track, pending a browser adapter).');
  out.push('');
  out.push('Every scenario cites the public disclosure it is derived from (`source.primary_url`, required by');
  out.push('the schema). The disclosure column links it; the date is the disclosure date recorded in the');
  out.push('scenario. `fix status` is the vendor fix status as recorded in the scenario (`patched`, `partial`,');
  out.push('`unpatched`, `na`); `tier` is `regression` (a patched, version-specific issue: a vulnerable');
  out.push('verdict is a regression signal) or `class` (a by-design or unpatched class). A scenario listed');
  out.push('here can still have its result withheld from published bundles pending coordinated disclosure');
  out.push('(ADR-0014); measured results per bundle are in [verified-against.md](verified-against.md).');
  out.push('Scenario files: [scenarios/](../scenarios/); field reference: [guide/scenarios.md](guide/scenarios.md).');
  out.push('');
  out.push('| id | name | surface | effect | disclosure | applies_to | runnable | fix status | tier |');
  out.push('|---|---|---|---|---|---|---|---|---|');
  for (const s of rows) {
    out.push('| ' + [
      `[${cell(s.id)}](../scenarios/${s.id}.yaml)`,
      cell(s.name),
      `\`${cell(s.surface)}\``,
      cell((s.effect ?? []).join(', ')),
      disclosure(s.source),
      cell((s.applies_to ?? []).join(', ') || '-'),
      s.runnable === true ? 'yes' : 'no',
      cell(s.source.fix_status ?? '-'),
      cell(s.tier ?? '-'),
    ].join(' | ') + ' |');
  }
  out.push('');
  const text = out.join('\n');
  if (/[^\x00-\x7f]/.test(text)) throw new Error('catalog is not pure ASCII');
  return text;
}

const mode = process.argv[2];
const text = generate();
if (mode === '--stdout') process.stdout.write(text);
else if (mode === '--check') {
  const cur = existsSync(OUT) ? readFileSync(OUT, 'utf8').replace(/\r\n/g, '\n') : '';
  if (cur !== text) { console.error('docs/catalog.md is stale: run npm run catalog'); process.exit(1); }
  console.log('docs/catalog.md is current');
} else if (mode === undefined) {
  writeFileSync(OUT, text);
  console.log(`docs/catalog.md: ${text.split('\n').length} lines`);
} else { console.error('usage: catalog.mjs [--check|--stdout]'); process.exit(2); }
